"use client";
/* Stickers, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Stickers(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("stickers"); }, []);
  return React.createElement("piix-stickers", piixAttrs(props));
}

export default Stickers;
